  return text.split("\n").map((line, i) => `${i + 1}: ${line}`).join("\n");
}

function parseAndValidate(raw: string, document: vscode.TextDocument): Segment[] {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new ValidationFailure("Response is not valid JSON");
